UITankIconNameGroup=function(game,maxNameWidth,iconsBelow){Phaser.Group.call(this,game,null);this.maxNameWidth=maxNameWidth;this.iconsBelow=iconsBelow||false;this.favouriteStar=this.addChild(new Phaser.Image(game,0,0,'favourite'));this.favouriteStar.anchor.set(0.5,0.5);this.favouriteStar.scale.setTo(0.0,0.0);this.favouriteStar.kill();this.tankName=this.addChild(new Phaser.Text(game,0,0,'',{font:UIConstants.USERNAME_FONT_SIZE+"px TankTrouble",fill:"#fff",strokeThickness:UIConstants.USERNAME_STROKE_WIDTH}));this.tankName.anchor.setTo(0.5,0.5);this.tankName.kill();this.rankIconGroup=this.addChild(new UIRankIconGroup(game));this.rankIconGroup.scale.setTo(0.0,0.0);this.rankIconGroup.remove();this.playerId=null;this.favourite=false;this.showRank=false;this.fitScale=1.0;this.spawnTween=null;this.removeTween=null;this.updateHideTween=null;this.updateShowTween=null;this.scale.set(0.0,0.0);this.exists=false;this.visible=false;this.log=Log.create('UITankIconNameGroup');};UITankIconNameGroup.prototype=Object.create(Phaser.Group.prototype);UITankIconNameGroup.prototype.constructor=UITankIconNameGroup;UITankIconNameGroup.prototype.update=function(){if(!this.exists){return;}Phaser.Group.prototype.update.call(this);};UITankIconNameGroup.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Group.prototype.postUpdate.call(this);};UITankIconNameGroup.prototype.spawn=function(x,y,playerId,targetScale,showRank){this.exists=true;this.visible=true;this.x=x;this.y=y;this.playerId=playerId;this.showRank=false;this.fitScale=1.0;this.targetScale=targetScale||1.0;this.rankIconGroup.scale.setTo(0.0,0.0);this.rankIconGroup.remove();this.favouriteStar.scale.setTo(0.0,0.0);this.favouriteStar.kill();this.tankName.setText('');if(this.removeTween){this.removeTween.stop();this.removeTween=null;}if(this.spawnTween){this.spawnTween.stop();this.spawnTween=null;}var self=this;Backend.getInstance().getPlayerDetails(function(result){if(typeof(result)=="object"){var username=Utils.maskUnapprovedUsername(result);self._updateUsernameAndRankLevel(username,result.getRank());self._updateRanked(showRank);}self._updateFavouriteStatus();},function(result){},function(result){},this.playerId,Caches.getPlayerDetailsCache());};UITankIconNameGroup.prototype.refresh=function(x,y,targetScale,showRank){if(x!==undefined){this.game.add.tween(this).to({x:x},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.InOut,true);}if(y!==undefined){this.game.add.tween(this).to({y:y},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.InOut,true);}if(showRank!==undefined){this._updateRanked(showRank);}if(targetScale!==undefined){this.targetScale=targetScale;this.game.add.tween(this.scale).to({x:this.fitScale*this.targetScale,y:this.fitScale*this.targetScale},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.InOut,true);if(this.favourite){this.game.add.tween(this.favouriteStar.scale).to({x:1.0/this.fitScale/this.targetScale,y:1.0/this.fitScale/this.targetScale},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.InOut,true);}if(this.showRank){this.game.add.tween(this.rankIconGroup.scale).to({x:1.0/this.fitScale/this.targetScale,y:1.0/this.fitScale/this.targetScale},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);}}this._updateFavouriteStatus();};UITankIconNameGroup.prototype.updateName=function(){if(this.spawnTween){this.spawnTween.stop();}if(!this.removeTween){if(this.updateHideTween){this.updateHideTween.stop();}if(this.updateShowTween){this.updateShowTween.stop();}this.updateHideTween=this.game.add.tween(this.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None);this.updateHideTween.onComplete.add(function(){var self=this;Backend.getInstance().getPlayerDetails(function(result){if(typeof(result)=="object"){var username=Utils.maskUnapprovedUsername(result);self._updateUsernameAndRankLevel(username,result.getRank());}self._updateFavouriteStatus();self.updateShowTween=self.game.add.tween(self.scale).to({x:self.fitScale*self.targetScale,y:self.fitScale*self.targetScale},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out);self.updateShowTween.start();},function(result){},function(result){},this.playerId,Caches.getPlayerDetailsCache());},this);this.updateHideTween.start();}};UITankIconNameGroup.prototype.updateRank=function(rank,rankChange){this._updateUsernameAndRankLevel(this.tankName.text,rank,rankChange);this._updateRanked(this.showRank);};UITankIconNameGroup.prototype._updateUsernameAndRankLevel=function(username,rank,rankChange){this.tankName.revive();this.tankName.setText(username);this.fitScale=Math.min(1.0,this.maxNameWidth/(this.tankName.width+UIConstants.FAVOURITE_ICON_WIDTH+UIConstants.RANK_ICON_WIDTH));if(!this.spawnTween){var delay=50+Math.random()*200;this.spawnTween=this.game.add.tween(this.scale).to({x:this.fitScale*this.targetScale,y:this.fitScale*this.targetScale},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true,delay);}var centerX=0;if(this.favourite){centerX+=UIConstants.FAVOURITE_ICON_WIDTH/2.0/this.fitScale/this.targetScale;}if(!this.iconsBelow&&this.showRank){centerX-=UIConstants.RANK_ICON_WIDTH/2.0/this.fitScale/this.targetScale;}if(rankChange){rank+=rankChange;GameManager.showRankChange(rankChange,UIPlayerPanel.getTankIconPosition(this.playerId));}var newRankLevel=UIUtils.getRankLevelFromRank(rank);this.rankIconGroup.updateRankLevel(newRankLevel);if(!this.iconsBelow){this.tankName.x=centerX;this.favouriteStar.x=centerX-this.tankName.width/2.0-UIConstants.FAVOURITE_ICON_WIDTH/this.fitScale/this.targetScale/2.0;this.rankIconGroup.x=centerX+this.tankName.width/2.0+UIConstants.RANK_ICON_WIDTH/this.fitScale/this.targetScale/2.0;}else{this.tankName.x=0;this.favouriteStar.x=centerX-(UIConstants.RANK_ICON_WIDTH+UIConstants.FAVOURITE_ICON_WIDTH)/this.fitScale/this.targetScale/2.0;this.rankIconGroup.x=centerX;this.favouriteStar.y=this.tankName.height/3.0+UIConstants.FAVOURITE_ICON_HEIGHT/this.fitScale/this.targetScale/2.0;this.rankIconGroup.y=this.tankName.height/3.0+UIConstants.RANK_ICON_HEIGHT/this.fitScale/this.targetScale/2.0;}};UITankIconNameGroup.prototype._updateRanked=function(newShowRank){if(newShowRank&&!this.showRank){this.rankIconGroup.spawn();this.game.add.tween(this.rankIconGroup.scale).to({x:1.0/this.fitScale/this.targetScale,y:1.0/this.fitScale/this.targetScale},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);}else if(!newShowRank&&this.showRank){this.game.add.tween(this.rankIconGroup.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);}this.showRank=newShowRank;var centerX=0;if(this.favourite){centerX+=UIConstants.FAVOURITE_ICON_WIDTH/2.0/this.fitScale/this.targetScale;}if(!this.iconsBelow&&this.showRank){centerX-=UIConstants.RANK_ICON_WIDTH/2.0/this.fitScale/this.targetScale;}if(!this.iconsBelow){this.game.add.tween(this.tankName).to({x:centerX},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);this.game.add.tween(this.favouriteStar).to({x:centerX-this.tankName.width/2.0-UIConstants.FAVOURITE_ICON_WIDTH/this.fitScale/this.targetScale/2.0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);this.game.add.tween(this.rankIconGroup).to({x:centerX+this.tankName.width/2.0+UIConstants.RANK_ICON_WIDTH/this.fitScale/this.targetScale/2.0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);}else{this.game.add.tween(this.tankName).to({x:0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);this.game.add.tween(this.favouriteStar).to({x:centerX-((this.showRank?UIConstants.RANK_ICON_WIDTH:0)+UIConstants.FAVOURITE_ICON_WIDTH)/this.fitScale/this.targetScale/2.0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);this.game.add.tween(this.rankIconGroup).to({x:centerX},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);}};UITankIconNameGroup.prototype._updateFavouriteStatus=function(){if(!this.playerId)return;this.favourite=false;var playerIds=Users.getAuthenticatedPlayerIds();var numFavouritesResponses=0;var numExpectedFavouritesResponses=playerIds.length;var favouritePlayerIds=[];var self=this;for(var i=0;i<playerIds.length;++i){Backend.getInstance().getFavourites(function(result){if(Array.isArray(result)){favouritePlayerIds=favouritePlayerIds.concat(result);}},function(result){},function(result){++numFavouritesResponses;if(numFavouritesResponses==numExpectedFavouritesResponses){for(var j=0;j<favouritePlayerIds.length;++j){if(favouritePlayerIds[j]==self.playerId){self.favourite=true;break;}}var centerX=0;if(self.favourite){centerX+=UIConstants.FAVOURITE_ICON_WIDTH/2.0/self.fitScale/self.targetScale;}if(!self.iconsBelow&&self.showRank){centerX-=UIConstants.RANK_ICON_WIDTH/2.0/self.fitScale/self.targetScale;}if(self.favourite){self.favouriteStar.revive();self.game.add.tween(self.favouriteStar.scale).to({x:1.0/self.fitScale/self.targetScale,y:1.0/self.fitScale/self.targetScale},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true);}else{self.game.add.tween(self.favouriteStar.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true).onComplete.add(function(){this.kill();},self.favouriteStar);}if(!self.iconsBelow){self.game.add.tween(self.tankName).to({x:centerX},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);self.game.add.tween(self.favouriteStar).to({x:centerX-self.tankName.width/2.0-UIConstants.FAVOURITE_ICON_WIDTH/self.fitScale/self.targetScale/2.0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);self.game.add.tween(self.rankIconGroup).to({x:centerX+self.tankName.width/2.0+UIConstants.RANK_ICON_WIDTH/self.fitScale/self.targetScale/2.0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);}else{self.game.add.tween(self.tankName).to({x:0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);self.game.add.tween(self.favouriteStar).to({x:centerX-((self.showRank?UIConstants.RANK_ICON_WIDTH:0)+UIConstants.FAVOURITE_ICON_WIDTH)/self.fitScale/self.targetScale/2.0},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);self.game.add.tween(self.rankIconGroup).to({x:centerX},UIConstants.ELEMENT_MOVE_TIME,Phaser.Easing.Quadratic.Out,true);}}},playerIds[i],Caches.getFavouritesCache());}};UITankIconNameGroup.prototype.remove=function(){if(this.spawnTween){this.spawnTween.stop();}if(this.updateHideTween){this.updateHideTween.stop();}if(this.updateShowTween){this.updateShowTween.stop();}this.removeTween=this.game.add.tween(this.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);this.removeTween.onComplete.add(function(){this.exists=false;this.visible=false;this.favouriteStar.kill();this.rankIconGroup.remove();this.tankName.kill();},this);};UITankIconNameGroup.prototype.retire=function(){this.exists=false;this.visible=false;this.favouriteStar.kill();this.rankIconGroup.retire();this.tankName.kill();};